#!/usr/bin/env python3
# Some portions generated by Codex. Freeze both independently compiled source variants after safety handoff.
import pathlib,sys,shutil,json,hashlib
p=pathlib.Path(__file__).resolve().parent;common=p.parent/'depth-workbench';previous=p.parent/'serializer-workbench'
assert len(sys.argv)==3,'base candidate directory and stack candidate directory required'
manifest={}
for name,src in zip(['base','stack'],sys.argv[1:]):
 src=pathlib.Path(src).resolve();dst=p/(name+'-candidate-layer');assert not dst.exists();files=list(src.rglob('*.class'));assert len(files)>=9
 assert all(any(f.name==n+'.class' or f.name.startswith(n+'$') for n in ['QueryEvaluator','TupleResultBuilder','WorkbenchPageResultWriter']) for f in files)
 shutil.copytree(src,dst);manifest[name]={str(f.relative_to(src)):hashlib.sha256(f.read_bytes()).hexdigest() for f in files}
for arm in ['base','stack','ordered','both']:
 cp=(common/('cp-depth.txt' if arm in ('stack','both') else 'cp-base.txt')).read_text().strip().split(':');cp[cp.index(str(common/'harness'))]=str(p/'harness')
 if arm=='stack':cp.insert(0,str(previous/'serializer-layer'))
 if arm in ('ordered','both'):cp.insert(0,str(p/('base-candidate-layer' if arm=='ordered' else 'stack-candidate-layer')))
 (p/f'cp-{arm}.txt').write_text(':'.join(cp)+'\n')
(p/'candidate-families.json').write_text(json.dumps(manifest,indent=2)+'\n')
